static int longestWithSum(int[] nums, long k) {
    Map<Long, Integer> first = new HashMap<>();
    first.put(0L, -1);
    long prefix = 0;
    int best = 0;
    for (int j = 0; j < nums.length; j++) {
        prefix += nums[j];
        Integer i = first.get(prefix - k);
        if (i != null) best = Math.max(best, j - i);
        first.putIfAbsent(prefix, j);
    }
    return best;
}

