int longestWithSum(const vector<int>& nums, long long k) {
    unordered_map<long long, int> first{{0, -1}};
    long long prefix = 0;
    int best = 0;
    for (int j = 0; j < (int)nums.size(); j++) {
        prefix += nums[j];
        auto it = first.find(prefix - k);
        if (it != first.end()) best = max(best, j - it->second);
        first.emplace(prefix, j);
    }
    return best;
}

