typedef struct {
    long long* keys;
    int* idx;
    bool* used;
    size_t mask;
} FirstMap;

static size_t fm_slot(const FirstMap* m, long long key) {
    size_t i = (size_t)(((uint64_t)key * 0x9E3779B97F4A7C15ull) >> 32) & m->mask;
    while (m->used[i] && m->keys[i] != key) i = (i + 1) & m->mask;
    return i;
}

static void fm_keep(FirstMap* m, long long key, int j) {
    size_t i = fm_slot(m, key);
    if (!m->used[i]) {
        m->used[i] = true;
        m->keys[i] = key;
        m->idx[i] = j;
    }
}

int longestWithSum(const int* nums, int n, long long k) {
    size_t cap = 16;
    while (cap < 2 * ((size_t)n + 1)) cap <<= 1;
    FirstMap first = {malloc(cap * sizeof(long long)), malloc(cap * sizeof(int)), calloc(cap, sizeof(bool)), cap - 1};
    fm_keep(&first, 0, -1);
    long long prefix = 0;
    int best = 0;
    for (int j = 0; j < n; j++) {
        prefix += nums[j];
        size_t i = fm_slot(&first, prefix - k);
        if (first.used[i] && j - first.idx[i] > best) best = j - first.idx[i];
        fm_keep(&first, prefix, j);
    }
    free(first.keys); free(first.idx); free(first.used);
    return best;
}

