// P is (rows + 1) x (cols + 1), stored row by row: P[r][c] lives at P[r * (cols + 1) + c].
long long* build2d(const int* grid, int rows, int cols) {
    int w = cols + 1;
    long long* P = calloc((size_t)(rows + 1) * w, sizeof(long long));
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            P[(r + 1) * w + c + 1] = grid[r * cols + c] + P[r * w + c + 1] + P[(r + 1) * w + c] - P[r * w + c];
        }
    }
    return P;
}

long long rectSum(const long long* P, int cols, int r1, int c1, int r2, int c2) {
    int w = cols + 1;
    return P[(r2 + 1) * w + c2 + 1] - P[r1 * w + c2 + 1] - P[(r2 + 1) * w + c1] + P[r1 * w + c1];
}
